result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/outbreak/outbreak.py", "content": """"Attack-rate / risk-ratio analysis for foodborne outbreak line lists.

Teaching module: invented attendee data embedded as CSV in tests.
Exposures are binary (ate / did not eat); outcome is binary (ill / well).

For each exposure we compute a 2x2 table:

                 ill   well   total
    exposed       a     b     a+b
    unexposed     c     d     c+d

Attack rate (AR) = ill / total within an exposure stratum.
Risk ratio RR = AR_exposed / AR_unexposed = [a/(a+b)] / [c/(c+d)].
Katz log CI: exp(ln RR +/- 1.96 * sqrt(1/a - 1/(a+b) + 1/c - 1/(c+d)))
"""

from __future__ import annotations

import csv
import io
import math
from dataclasses import dataclass

EXPOSURES = ("salad", "chicken", "cake")
Z = 1.96


@dataclass(frozen=True)
class TwoByTwo:
    exposure: str
    a: int  # exposed & ill
    b: int  # exposed & well
    c: int  # unexposed & ill
    d: int  # unexposed & well

    @property
    def ar_exposed(self) -> float:
        return self.a / (self.a + self.b)

    @property
    def ar_unexposed(self) -> float:
        return self.c / (self.c + self.d)


@dataclass(frozen=True)
class ExposureResult:
    table: TwoByTwo
    rr: float | None
    ci_low: float | None
    ci_high: float | None
    note: str | None = None


def parse_line_list(csv_text: str) -> list[dict[str, object]]:
    """Parse the inline CSV into rows of typed values."""
    reader = csv.DictReader(io.StringIO(csv_text.strip()))
    rows = []
    for r in reader:
        rows.append(
            {
                "attendee": r["attendee"].strip(),
                "salad": int(r["ate_salad"]),
                "chicken": int(r["ate_chicken"]),
                "cake": int(r["ate_cake"]),
                "ill": int(r["ill"]),
            }
        )
    return rows


def make_table(rows: list[dict[str, object]], exposure: str) -> TwoByTwo:
    """Collapse the line list into a 2x2 table for one exposure."""
    a = b = c = d = 0
    for r in rows:
        exposed = bool(r[exposure])
        if r["ill"]:
            if exposed:
                a += 1
            else:
                c += 1
        else:
            if exposed:
                b += 1
            else:
                d += 1
    return TwoByTwo(exposure=exposure, a=a, b=b, c=c, d=d)


def katz_rr(table: TwoByTwo) -> ExposureResult:
    """RR eaten-vs-not with Katz log CI. Returns None + note on zero cells."""
    a, b, c, d = table.a, table.b, table.c, table.d

    # Degenerate denominators or zero cells: RR is undefined. We deliberately
    # do NOT apply a continuity (Haldane-Anscombe 0.5) correction silently --
    # for teaching we surface it as a note instead of fabricating a value.
    if (a + b) == 0 or (c + d) == 0:
        return ExposureResult(
            table,
            None,
            None,
            None,
            note="undefined: an exposure stratum has zero total attendees",
        )
    if a == 0 or c == 0:
        which = "exposed-ill (a)" if a == 0 else "unexposed-ill (c)"
        return ExposureResult(
            table,
            None,
            None,
            None,
            note=(
                f"zero cell {which}: RR undefined/infinite; a Haldane-Anscombe "
                "+0.5 continuity correction could be applied but is NOT applied here"
            ),
        )

    ar1, ar0 = a / (a + b), c / (c + d)
    rr = ar1 / ar0
    se = math.sqrt(1 / a - 1 / (a + b) + 1 / c - 1 / (c + d))
    lo = math.exp(math.log(rr) - Z * se)
    hi = math.exp(math.log(rr) + Z * se)
    return ExposureResult(table, rr, lo, hi)


def analyze(csv_text: str) -> list[ExposureResult]:
    """Full per-exposure analysis, ranked by RR descending (None last)."""
    rows = parse_line_list(csv_text)
    results = []
    for exp in EXPOSURES:
        res = katz_rr(make_table(rows, exp))
        if res is not None:
            results.append(res)
    results.sort(key=lambda r: (r.rr is None, -(r.rr if r.rr is not None else 0.0)))
    return results


def format_report(results: list[ExposureResult], n_total: int, n_ill: int) -> str:
    lines = [
        "=" * 72,
        "FOODBORNE OUTBREAK ATTACK-RATE ANALYSIS (teaching line list)",
        "=" * 72,
        f"Attendees: {n_total}    Ill: {n_ill}    Overall AR: {n_ill / n_total:.2f}",
        "",
        f"{'Exposure':<10} {'Ate':>4} {'Ill':>4} {'AR_exp':>7} {'Not':>4} "
        f"{'Ill':>4} {'AR_unexp':>8} {'RR':>6} {'95% CI (Katz)':>20}",
        "-" * 72,
    ]
    for res in results:
        t = res.table
        ci = (
            f"{res.ci_low:.2f}-{res.ci_high:.2f}"
            if res.ci_low is not None
            else "n/a"
        )
        rr = f"{res.rr:.2f}" if res.rr is not None else "None"
        lines.append(
            f"{t.exposure:<10} {t.a:>4} {t.a:>4} {t.ar_exposed:>7.2f} "
            f"{t.c + t.d:>4} {t.c:>4} {t.ar_unexposed:>8.2f} {rr:>6} {ci:>20}"
        )
        if res.note:
            lines.append(f"           note: {res.note}")
    lines += ["-" * 72, "Ranked by RR (descending). CI excludes 1 => association.", "=" * 72]
    return "\n".join(lines)


if __name__ == "__main__":
    import sys

    from tests.fixtures import LINE_LIST_CSV

    rows = parse_line_list(LINE_LIST_CSV)
    print(format_report(analyze(LINE_LIST_CSV), len(rows), sum(r["ill"] for r in rows)))
"})
print(result)

result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/tests/test_outbreak.py", "content": "import pytest

from outbreak.outbreak import (
    EXPOSURES,
    TwoByTwo,
    analyze,
    format_report,
    katz_rr,
    make_table,
    parse_line_list,
)
from tests.fixtures import LINE_LIST_CSV


@pytest.fixture(scope="module")
def rows():
    return parse_line_list(LINE_LIST_CSV)


@pytest.fixture(scope="module")
def results():
    return {r.table.exposure: r for r in analyze(LINE_LIST_CSV)}


# ---------------------------------------------------------------- fixture sums

def test_line_list_has_40_rows(rows):
    assert len(rows) == 40


def test_constructed_marginals_sum_to_40(rows):
    for exp in EXPOSURES:
        t = make_table(rows, exp)
        assert (t.a + t.b + t.c + t.d) == 40


def test_total_ill_is_26(rows):
    assert sum(r["ill"] for r in rows) == 26


def test_salad_construction_exact(rows):
    t = make_table(rows, "salad")
    assert (t.a, t.b, t.c, t.d) == (24, 6, 2, 8)


def test_chicken_construction_exact(rows):
    t = make_table(rows, "chicken")
    assert (t.a, t.b, t.c, t.d) == (13, 7, 13, 7)


def test_cake_construction_exact(rows):
    t = make_table(rows, "cake")
    assert (t.a, t.b, t.c, t.d) == (9, 6, 17, 8)


# ------------------------------------------------------- pinned point estimates

def test_salad_attack_rates_pinned(rows):
    t = make_table(rows, "salad")
    assert t.ar_exposed == pytest.approx(0.80)
    assert t.ar_unexposed == pytest.approx(0.20)


def test_salad_rr_exactly_4(results):
    assert results["salad"].rr == pytest.approx(4.0)


def test_chicken_rr_exactly_1(results):
    assert results["chicken"].rr == pytest.approx(1.0)


def test_cake_rr_value(results):
    assert results["cake"].rr == pytest.approx((9 / 15) / (17 / 25))


# ------------------------------------------------------------------ Katz CI

def test_salad_katz_ci_matches_hand_computation():
    # a=24,b=6,c=2,d=8: se = sqrt(1/24 - 1/30 + 1/2 - 1/10)
    import math

    rr = 4.0
    se = math.sqrt(1 / 24 - 1 / 30 + 1 / 2 - 1 / 10)
    res = katz_rr(TwoByTwo("salad", 24, 6, 2, 8))
    assert res.ci_low == pytest.approx(math.exp(math.log(rr) - 1.96 * se))
    assert res.ci_high == pytest.approx(math.exp(math.log(rr) + 1.96 * se))
    assert res.ci_low > 1  # excludes 1


def test_salad_ci_excludes_1_chicken_includes_1(results):
    s = results["salad"]
    assert s.ci_low > 1.0 < s.ci_high or (s.ci_low > 1.0 and s.ci_high > s.ci_low)
    assert s.ci_low > 1.0 and s.ci_high > 1.0  # entirely above 1
    c = results["chicken"]
    assert c.ci_low < 1.0 < c.ci_high


# --------------------------------------------- zero-cell handling: no crash

def test_zero_cell_returns_none_with_continuity_note():
    # nobody ill among the unexposed (c = 0)
    res = katz_rr(TwoByTwo("icecream", 10, 5, 0, 20))
    assert res.rr is None
    assert res.ci_low is None and res.ci_high is None
    assert res.note is not None
    assert "continuity" in res.note.lower()
    assert "+0.5" in res.note


def test_zero_stratum_returns_none():
    res = katz_rr(TwoByTwo("water", 5, 5, 3, 0))
    assert res.rr is None
    assert res.note is not None


def test_analyze_never_crashes_on_degenerate_row():
    csv_text = (
        "attendee,ate_salad,ate_chicken,ate_cake,ill\n"
        "A01,1,1,1,1\nA02,1,1,1,0\n"
    )
    res = {r.table.exposure: r for r in analyze(csv_text)}
    for exp in ("salad", "chicken", "cake"):
        assert exp in res
        if res[exp].rr is None:
            assert res[exp].note


# ------------------------------------------------------------------- ranking

def test_ranked_by_rr_descending(results):
    ranked = [r.table.exposure for r in analyze(LINE_LIST_CSV)]
    rrs = [results[e].rr for e in ranked]
    assert rrs == sorted(rrs, reverse=True)
    assert ranked[0] == "salad"


# -------------------------------------------------------------------- report

def test_report_renders_with_all_sections(results):
    report = format_report(
        list(analyze(LINE_LIST_CSV)), n_total=40, n_ill=26
    )
    assert "ATTACK-RATE ANALYSIS" in report
    for exp in ("salad", "chicken", "cake"):
        assert exp in report
    assert "4.00" in report and "1.00" in report
